@Test
void nonEmptyMcpConfigurationFailsClosed() throws Exception {
    var store = new MemoryHostStore();
    try (var runtime = new AgentRuntimeBuilder().provider(new ScriptedModelProvider())
            .sessionRepository(store).build();
         var sessions = new SessionApplicationService(runtime);
         var harness = new Harness(sessions, new PromptApplicationService(sessions, store))) {
        harness.request(1, "initialize", initializeParams());
        harness.request(2, "auth/login", Map.of("methodId", "local"));
        JsonNode response = harness.request(3, "session/new", Map.of("cwd", ".",
                "mcpServers", List.of(Map.of("name", "unsupported", "command", "server"))));
        assertEquals(-32005, response.path("error").path("code").asInt());
        assertEquals("protocol.capability_not_supported",
                response.path("error").path("data").path("code").asText());
    }
}

